package com.mall.model;

/**
 * Model class encapsulating a reorder recommendation generated by DemandPredictor.
 * 
 * Demonstrates:
 * - Collections & Algorithms: Comparable<T> interface implementation
 * - Natural ordering designed specifically for java.util.PriorityQueue (Min-Heap)
 * - Sorting criteria:
 *   1. Urgency Level (CRITICAL rank 1 < WARNING rank 2 < SAFE rank 3)
 *   2. Days until stockout ascending (0 days is more urgent than 2 days)
 *   3. Product ID alphanumeric tie-breaker
 */
public class ReorderSuggestion implements Comparable<ReorderSuggestion> {
    private final Product product;
    private final int currentStock;
    private final double avgDailySales;
    private final int daysUntilStockout;
    private final int suggestedQuantity;
    private final UrgencyLevel urgency;
    private final String rationale;

    public ReorderSuggestion(Product product, int currentStock, double avgDailySales, 
                             int daysUntilStockout, int suggestedQuantity, 
                             UrgencyLevel urgency, String rationale) {
        this.product = product;
        this.currentStock = currentStock;
        this.avgDailySales = avgDailySales;
        this.daysUntilStockout = daysUntilStockout;
        this.suggestedQuantity = suggestedQuantity;
        this.urgency = urgency;
        this.rationale = rationale;
    }

    /**
     * Comparable implementation used by PriorityQueue to order items by urgency.
     * Return negative if 'this' is MORE urgent than 'other' (comes first in PriorityQueue).
     */
    @Override
    public int compareTo(ReorderSuggestion other) {
        if (other == null) {
            return -1;
        }

        // 1. Primary sort: Urgency Rank (1=CRITICAL, 2=WARNING, 3=SAFE)
        int rankDiff = Integer.compare(this.urgency.getPriorityRank(), other.urgency.getPriorityRank());
        if (rankDiff != 0) {
            return rankDiff;
        }

        // 2. Secondary sort: Days until stockout (Ascending: fewer days = more urgent)
        int daysDiff = Integer.compare(this.daysUntilStockout, other.daysUntilStockout);
        if (daysDiff != 0) {
            return daysDiff;
        }

        // 3. Tertiary tie-breaker: Product ID
        return this.product.getId().compareToIgnoreCase(other.product.getId());
    }

    public Product getProduct() {
        return product;
    }

    public int getCurrentStock() {
        return currentStock;
    }

    public double getAvgDailySales() {
        return avgDailySales;
    }

    public int getDaysUntilStockout() {
        return daysUntilStockout;
    }

    public int getSuggestedQuantity() {
        return suggestedQuantity;
    }

    public UrgencyLevel getUrgency() {
        return urgency;
    }

    public String getRationale() {
        return rationale;
    }

    @Override
    public String toString() {
        return String.format("[%s] %-18s | Stock: %-3d | Days Left: %-3d | Reorder Qty: %-4d | Urgency: %-8s",
                product.getId(), product.getName(), currentStock, daysUntilStockout, suggestedQuantity, urgency.getLabel());
    }
}
